#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles with padding to avoid bank conflicts
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Register arrays for accumulation
    float sum[BLOCK_SIZE][BLOCK_SIZE] = {0};

    // Calculate thread block boundaries
    int aBegin = N * TILE_SIZE * by;
    int aEnd = aBegin + N - 1;
    int aStep = TILE_SIZE;
    int bBegin = TILE_SIZE * bx;
    int bStep = TILE_SIZE * N;

    // Loop over tiles
    for (int a = aBegin, b = bBegin; a <= aEnd; a += aStep, b += bStep) {
        // Load tiles into shared memory
        for (int i = 0; i < BLOCK_SIZE; i++) {
            for (int j = 0; j < BLOCK_SIZE; j++) {
                int row = ty * BLOCK_SIZE + i;
                int col = tx * BLOCK_SIZE + j;

                if (row < TILE_SIZE && col < TILE_SIZE) {
                    int aIdx = a + N * row + col;
                    int bIdx = b + N * row + col;

                    if (aIdx < N * N && (a + N * row + col) / N < N && (a + N * row + col) % N < N) {
                        As[row][col] = A[aIdx];
                    } else {
                        As[row][col] = 0.0f;
                    }

                    if (bIdx < N * N && (b + N * row + col) / N < N && (b + N * row + col) % N < N) {
                        Bs[row][col] = B[bIdx];
                    } else {
                        Bs[row][col] = 0.0f;
                    }
                }
            }
        }

        __syncthreads();

        // Compute partial sums
        for (int k = 0; k < TILE_SIZE; k++) {
            for (int i = 0; i < BLOCK_SIZE; i++) {
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    int row = ty * BLOCK_SIZE + i;
                    int col = tx * BLOCK_SIZE + j;
                    if (row < TILE_SIZE && col < TILE_SIZE) {
                        sum[i][j] += As[row][k] * Bs[k][col];
                    }
                }
            }
        }

        __syncthreads();
    }

    // Write results
    for (int i = 0; i < BLOCK_SIZE; i++) {
        for (int j = 0; j < BLOCK_SIZE; j++) {
            int row = by * TILE_SIZE + ty * BLOCK_SIZE + i;
            int col = bx * TILE_SIZE + tx * BLOCK_SIZE + j;
            if (row < N && col < N) {
                C[row * N + col] = sum[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block(TILE_SIZE / BLOCK_SIZE, TILE_SIZE / BLOCK_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
