# Define the optimized CUDA kernel for matrix multiplication with double buffering
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define THREAD_BLOCK_SIZE 256

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    // Double buffered shared memory
    __shared__ float As[2][TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[2][TILE_SIZE][TILE_SIZE];

    // Thread and block indices
    int tid = threadIdx.x;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Convert 1D thread index to 2D tile coordinates
    int tx = tid % TILE_SIZE;
    int ty = tid / TILE_SIZE;

    // Output position
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;

    // Handle case where we have more threads than needed
    if (tid >= TILE_SIZE * TILE_SIZE) {
        // Extra threads just wait
        return;
    }

    // Preload first tile
    int buffer = 0;
    if (ty < TILE_SIZE && tx < TILE_SIZE) {
        int a_row = by * TILE_SIZE + ty;
        int a_col = tx;
        int b_row = ty;
        int b_col = bx * TILE_SIZE + tx;

        if (a_row < N && a_col < N) {
            As[buffer][ty][tx] = A[a_row * N + a_col];
        } else {
            As[buffer][ty][tx] = 0.0f;
        }

        if (b_row < N && b_col < N) {
            Bs[buffer][ty][tx] = B[b_row * N + b_col];
        } else {
            Bs[buffer][ty][tx] = 0.0f;
        }
    }

    // Main computation loop with double buffering
    for (int t = 0; t < num_tiles; t++) {
        __syncthreads();

        // Load next tile while computing current
        int next_buffer = 1 - buffer;
        if (t + 1 < num_tiles && ty < TILE_SIZE && tx < TILE_SIZE) {
            int a_row = by * TILE_SIZE + ty;
            int a_col = (t + 1) * TILE_SIZE + tx;
            int b_row = (t + 1) * TILE_SIZE + ty;
            int b_col = bx * TILE_SIZE + tx;

            if (a_row < N && a_col < N) {
                As[next_buffer][ty][tx] = A[a_row * N + a_col];
            } else {
                As[next_buffer][ty][tx] = 0.0f;
            }

            if (b_row < N && b_col < N) {
                Bs[next_buffer][ty][tx] = B[b_row * N + b_col];
            } else {
                Bs[next_buffer][ty][tx] = 0.0f;
            }
        }

        // Compute using current buffer
        if (ty < TILE_SIZE && tx < TILE_SIZE) {
            #pragma unroll 8
            for (int k = 0; k < TILE_SIZE; k++) {
                sum += As[buffer][ty][k] * Bs[buffer][k][tx];
            }
        }

        buffer = next_buffer;
    }

    // Write result
    if (row < N && col < N && ty < TILE_SIZE && tx < TILE_SIZE) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Ensure tensors are contiguous
    A = A.contiguous();
    B = B.contiguous();

    dim3 block(THREAD_BLOCK_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

